Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "dataset"
  },
  "width": 453,
  "height": 43,
  "padding": 0,
  "autosize": {
    "type": "none"
  },
  "background": "transparent",
  "config": {
    "view": {
      "stroke": null
    }
  },
  "transform": [
    {
      "calculate": "datum[''__selected__''] == ''on'' ? 1 : 0",
      "as": "isOn"
    },
    {
      "calculate": "[138, 219, 300.5, 399.5][datum[''Relationship Order''] - 1]",
      "as": "cx"
    },
    {
      "calculate": "[94, 58, 95, 93][datum[''Relationship Order''] - 1]",
      "as": "w"
    },
    {
      "calculate": "datum.cx - datum.w / 2",
      "as": "x1"
    },
    {
      "calculate": "datum.cx + datum.w / 2",
      "as": "x2"
    }
  ],
  "layer": [
    {
      "transform": [
        {
          "filter": "datum.isOn == 1"
        }
      ],
      "mark": {
        "type": "rect",
        "cornerRadius": 16.5,
        "fill": "#C9A45C"
      },
      "encoding": {
        "x": {
          "field": "x1",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "x2": {
          "field": "x2"
        },
        "y": {
          "value": 5
        },
        "y2": {
          "value": 38
        }
      }
    },
    {
      "mark": {
        "type": "rect",
        "fill": "#FFFFFF",
        "opacity": 0,
        "cursor": "pointer"
      },
      "encoding": {
        "x": {
          "field": "x1",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "x2": {
          "field": "x2"
        },
        "y": {
          "value": 5
        },
        "y2": {
          "value": 38
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.isOn == 1"
        }
      ],
      "mark": {
        "type": "text",
        "font": "Plus Jakarta Sans",
        "fontSize": 12,
        "fontWeight": 700,
        "fill": "#17140F",
        "align": "center",
        "baseline": "middle",
        "cursor": "pointer"
      },
      "encoding": {
        "x": {
          "field": "cx",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "y": {
          "value": 22
        },
        "text": {
          "field": "banking_relationship",
          "type": "nominal"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.isOn == 0"
        }
      ],
      "mark": {
        "type": "text",
        "font": "Plus Jakarta Sans",
        "fontSize": 12,
        "fontWeight": 400,
        "fill": "#2F2B26",
        "align": "center",
        "baseline": "middle",
        "cursor": "pointer"
      },
      "encoding": {
        "x": {
          "field": "cx",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "y": {
          "value": 22
        },
        "text": {
          "field": "banking_relationship",
          "type": "nominal"
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "sum",
              "field": "isOn",
              "as": "nOn"
            }
          ]
        }
      ],
      "mark": {
        "type": "rect",
        "cornerRadius": 16.5,
        "cursor": "pointer"
      },
      "encoding": {
        "x": {
          "value": 6
        },
        "x2": {
          "value": 87
        },
        "y": {
          "value": 5
        },
        "y2": {
          "value": 38
        },
        "fill": {
          "condition": {
            "test": "datum.nOn == 0",
            "value": "#C9A45C"
          },
          "value": "#F6F4EF"
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "sum",
              "field": "isOn",
              "as": "nOn"
            }
          ]
        }
      ],
      "mark": {
        "type": "text",
        "font": "Plus Jakarta Sans",
        "fontSize": 12,
        "align": "center",
        "baseline": "middle",
        "cursor": "pointer",
        "text": "All clients"
      },
      "encoding": {
        "x": {
          "value": 46.5
        },
        "y": {
          "value": 22
        },
        "fill": {
          "condition": {
            "test": "datum.nOn == 0",
            "value": "#17140F"
          },
          "value": "#2F2B26"
        },
        "fontWeight": {
          "condition": {
            "test": "datum.nOn == 0",
            "value": 700
          },
          "value": 400
        }
      }
    }
  ]
}'
